type LoginState =
  | { kind: "idle"; email: string }
  | { kind: "busy"; email: string };

export class LoginModel {
  constructor(private state: LoginState = { kind: "idle", email: "" }) {}
  get submitEnabled(): boolean { return this.state.kind === "idle" && this.state.email !== ""; }
  submit(): void { this.state = { kind: "busy", email: this.state.email }; this.notify(); }
  private notify(): void { /* call subscribers */ }
}
